mapper.update:
update todo_sla_record s join todo_instance t on t.todo_id=s.todo_id
s.remind80_at=#{now},t.sla_status='REMINDED's.overdue100_at=#{now},t.sla_status='OVERDUE's.escalate150_at=#{now},t.sla_status='ESCALATED',s.version=s.version+1
where s.todo_id=#{todoId} and s.version=#{expectedVersion}

  and s.remind80_at is null and s.due_at=#{expectedDueAt} and s.remind80_due_at=#{plannedDueAt} and s.remind80_due_at<=#{now}and s.remind80_due_at is null and s.due_at=#{expectedDueAt}
  and s.overdue100_at is null and s.due_at=#{expectedDueAt} and s.overdue100_due_at=#{plannedDueAt} and s.overdue100_due_at<=#{now}and s.overdue100_due_at is null and s.due_at=#{expectedDueAt}
  and s.escalate150_at is null and s.due_at=#{expectedDueAt} and s.escalate150_due_at=#{plannedDueAt} and s.escalate150_due_at<=#{now}and s.escalate150_due_at is null and s.due_at=#{expectedDueAt}

mapper.insert:
insert into todo_extension_request(todo_id,request_action_id,status,original_due_at,requested_due_at,request_reason,proof_file_ids_json,requester_id,requester_name,requester_dept_id,policy_version_id,pending_sla_mode)
select #{todoId},#{requestActionId},'PENDING',#{originalDueAt},#{requestedDueAt},#{reason},#{proofFileIdsJson},#{requesterId},#{requesterName},#{requesterDeptId},#{policyVersionId},#{pendingSlaMode}
where not exists(select 1 from todo_extension_request existing where existing.todo_id=#{todoId} and existing.status='PENDING')

insert into todo_instance(todo_no,template_id,template_version_id,template_code,title,business_type,business_id,business_no,business_stage,owner_id,owner_dept_id,status,priority,sla_status,created_at,due_at,previous_todo_id,root_todo_id,trigger_idempotency_key,dod_snapshot_json,version,create_by)
select concat('REGEN-',#{actionId},'-',todo_id),template_id,template_version_id,template_code,title,business_type,business_id,business_no,business_stage,owner_id,owner_dept_id,'CREATED',priority,'NORMAL',sysdate(),due_at,todo_id,coalesce(root_todo_id,todo_id),concat('REGENERATE:',#{actionId}),dod_snapshot_json,0,#{operator}
from todo_instance where todo_id=#{sourceTodoId}
